// Bundles data + sources into one ES module: dist/worker.js
import fs from "node:fs";
import path from "node:path";
const root = path.resolve(path.dirname(new URL(import.meta.url).pathname), "..");
const rd = (p) => fs.readFileSync(path.join(root, p), "utf8");
const out = [
  "// GENERATED by scripts/build.mjs — do not edit. Source: src/*.js, data/*.json",
  "const STATE_JUDGMENTS = " + JSON.stringify(JSON.parse(rd("data/state-judgments.json"))) + ";",
  "const FAQS = " + JSON.stringify(JSON.parse(rd("data/faqs.json"))) + ";",
  rd("src/content.js"),
  rd("src/judgment.js"),
  rd("src/worker.js"),
].join("\n");
fs.mkdirSync(path.join(root, "dist"), { recursive: true });
fs.writeFileSync(path.join(root, "dist/worker.js"), out);
console.log("dist/worker.js", out.length, "bytes");
